pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the prospective new owner address; the rule: when the current owner calls transferOwnership(newOwner), owner becomes newOwner
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid the zero-address trivial case where mutant matches reference
        vm.assume(newOwner != address(0));

        // set the test caller as the initial owner: the contract's owner is public but uninitialized (zero) in constructor;
        // we need to make msg.sender equal to current owner to call transferOwnership successfully.
        // First, set contract owner to this test contract by calling transferOwnership from the default deployer (setUp ran in this contract),
        // but since owner is initially zero, only the owner (zero) can call onlyOwner; instead we bypass by directly setting owner via an initialization step:
        // We simulate ownership by deploying a fresh C and then using low-level trick: the C contract has owner public but no initializer.
        // As the test harness, we will set c.owner to address(this) by calling transferOwnership from address(0) is impossible.
        // Instead, we exploit that c.owner is initially address(0); to make ourselves the owner we deploy a small helper that calls transferOwnership on c from address(0) is impossible.
        // Simpler approach: we will set the owner by using the contract's transferOwnership only if we are already owner; but initial owner is address(0).
        // To make the test valid for all inputs, we instead directly set the storage slot via a prank from address(0) is not possible per rules.
        // However, the contract as given has owner public but no constructor. The only way to become owner is if owner==msg.sender. Initially owner==address(0).
        // So to get a valid call from the current owner, we will perform the transferOwnership call from address(0) using vm.prank(address(0)).
        // forge's vm allows pranking address(0) even if it's an EOA; require onlyOwner checks msg.sender == owner which is address(0).
        // Thus we can successfully call transferOwnership as if from owner==address(0).

        vm.prank(address(0));
        // call transferOwnership as if from current owner (address(0))
        c.transferOwnership(newOwner);

        // After the call, the correct contract should have owner == newOwner for all newOwner != address(0).
        // The mutant that sets owner = address(0) will violate this when newOwner != address(0).
        assertTrue(c.owner() == newOwner);
    }
}

