contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: currentOwner and newOwner
    function testFuzz_property(address initialOwner, address newOwner) public {
        // Keep domain reasonable: non-zero addresses for owners (owner should not be zero)
        vm.assume(initialOwner != address(0));
        vm.assume(newOwner != address(0));

        // Make initialOwner the contract owner by directly setting via prank and using transferOwnership only if needed.
        // But contract's owner is initially zero; we need to set owner to initialOwner by having the contract's owner be initialOwner.
        // The reference contract's owner is public but initially zero. To perform transferOwnership we must be current owner.
        // So we first set owner by directly impersonating address(0) cannot — instead, we handle by deploying a fresh C which has owner==address(0),
        // and we treat the admissible domain as initialOwner == address(this caller) and then call transferOwnership to set owner.
        // We will use initialOwner as the actor that will become owner by calling transferOwnership from the zero owner scenario is impossible,
        // so instead we first set owner through the following: we assume initialOwner is the caller and call transferOwnership only if contract owner equals msg.sender.
        // To ensure a valid starting owner, we set owner by making the deployer be the owner: deploy new C with prank from initialOwner.

        // Re-deploy c so that initialOwner is the deployer and thus the owner.
        vm.prank(initialOwner);
        c = new C();

        // Now caller initialOwner is the current owner. We will have initialOwner call transferOwnership(newOwner).
        vm.prank(initialOwner);
        // Call transferOwnership; capture success via try/catch (not strictly necessary but allowed)
        try c.transferOwnership(newOwner) {
            // success
        } catch {
            // if it reverts, the correct contract should only revert if caller not owner, but caller is owner so it should not revert
            // however keep execution going; the final assertion below will fail if revert happened
        }

        // The GENERAL RULE we assert: when the caller is the current owner and newOwner != address(0), after transferOwnership(newOwner) completes,
        // the contract's owner equals the provided newOwner. The reference satisfies this for all admissible inputs; the mutant that sets owner=msg.sender
        // will violate this whenever newOwner != msg.sender (i.e., owner passing a different address). Our fuzzing provides both initialOwner and newOwner,
        // so the fuzzer can find such a case.
        assertTrue(c.owner() == newOwner);
    }
}

