        vm.assume(newOwner != address(0));

        // make this contract the owner by directly setting owner via transferOwnership from deployer
        // The deployed C.owner is zero initially; need to set owner to address(this).
        // Since transferOwnership is protected by onlyOwner, we must simulate owner being this contract.
        // Workaround: deploy a fresh C where owner is implicitly zero and then use self-call via low-level trick:
        // But simpler: use an address that is already owner: upon deployment owner is zero, so set owner to address(this)
        // by first making the contract think msg.sender == owner via a helper that can call with msg.sender==address(0) is impossible.
        // Instead, we'll assume contract's owner is address(this) by directly assigning through a privileged path is not available.
        // However, we can make address(this) the owner by first transferring ownership from zero to this contract via a call as zero
        // which we cannot do. To satisfy constraints, we instead use the fact that onlyOwner requires msg.sender == owner;
        // so we set c.owner() to address(this) by deploying a new C and then using self-destruct trick is disallowed.
        // Simpler approach: we will use the fact that on correct C, if the current owner calls transferOwnership(newOwner), owner becomes newOwner.
        // So we make the current owner be address(this) by deploying C and then directly setting storage is not allowed.
        // Instead, we create an OwnerSetter helper that is constructed with the C instance and performs a call from the current owner (zero)
        // but since onlyOwner initial owner is zero, we can have a helper contract deployed at address(0)? Not possible.
        // Alternate practical approach: we will make the test act as the zero address owner by deploying C2 via tx.origin zero is impossible.
        // To keep within allowed operations, we instead exploit that the test contract can become owner by calling transferOwnership when owner==address(this).
        // So we first make owner==address(this) by calling transferOwnership from address(0) is impossible; therefore we will instead
        // check the invariant in a slightly different admissible domain: call transferOwnership when the caller is the current owner;
        // we can ensure the caller is the current owner by first setting owner to address(this) using transferOwnership called by address(this).
        // That works only if owner already equals address(this). To bootstrap, if owner is zero, we can impersonate zero via vm.prank.

        // Bootstrapping: if c.owner() is address(0), impersonate address(0) (the initial owner) to transfer ownership to address(this)
        address initialOwner = c.owner();
        if (initialOwner == address(0)) {
            // impersonate zero address to call transferOwnership(address(this))
            vm.prank(address(0));
            // call succeeds on reference (since msg.sender == owner == address(0))
            c.transferOwnership(address(this));
        }

        // now this contract should be owner
        assertTrue(c.owner() == address(this));

        // now, as the owner, call transferOwnership(newOwner)
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Single assertion: after the owner calls transferOwnership(newOwner), the contract's owner getter equals newOwner.
        assertTrue(c.owner() == newOwner);
    }
}
